  {
    from: 'Mark Olsen <mark.olsen@gmail.com>',
    subject: "Can't log in to my account",
    text: "Hi, I forgot my password and now I'm locked out. How do I reset it? Thanks, Mark",
  },
  {
    from: 'Priya Natarajan <priya@northwind.co>',
    subject: 'URGENT: API returning 500 errors in production',
    text: 'Since 9am every call to your orders API returns a 500 error. Our checkout is down and we are losing sales. We need someone on this right now.',
  },
  {
    from: 'Tom Becker <tom.becker@outlook.com>',
    subject: 'Refund NOW',
    text: "This is the second time my order arrived broken. I want my money back today or I'm filing a chargeback. Absolutely unacceptable.",
  },
  {
    from: 'Sarah Chen <sarah.chen@brightpixel.io>',
    subject: 'Where can I find my invoices?',
    text: 'Hi team, our accountant needs last month\'s invoice and I need to add our VAT number to it. Where do I do that? Thanks!',
  },
  {
    from: 'Jess Walker <jess@freshbakery.ca>',
    subject: 'Shipping to Canada?',
    text: "Hello! I'm thinking about ordering for my bakery. Do you ship to Canada, and how long does delivery usually take?",
  },
];

return emails.map((e, i) => {
  const [, name, address] = e.from.match(/^(.*) <(.*)>$/);
  return {
    json: {
      id: `sample-${i + 1}`,
      threadId: `sample-thread-${i + 1}`,
      from: { value: [{ name, address }] },
      subject: e.subject,
      text: e.text,
    },
  };
});

