// Business rules: what the AI may answer on its own vs. what a human must see
const AUTO_SEND_CATEGORIES = ['account', 'billing', 'shipping'];
const AUTO_SEND_MIN_CONFIDENCE = 0.85;

return $input.all().map((item, i) => {
  const ticket = $('Match customer & attach KB articles').itemMatching(i).json;
  const ai = item.json.output;
  const reasons = [];

  if (ai.needs_human) reasons.push('AI could not answer from the knowledge base');
  if (ai.category === 'refund') reasons.push('Refund request');
  if (ai.sentiment === 'angry') reasons.push('Angry customer');
  if (ai.urgency === 'high') reasons.push('High urgency');
  if (ticket.plan === 'Enterprise') reasons.push('Enterprise account');

  let route;
  if (ai.category === 'spam') {
    route = 'spam';
    reasons.push('Spam');
  } else if (reasons.length) {
    route = 'escalate';
  } else if (!ticket.is_customer) {
    route = 'draft';
    reasons.push('New lead (not yet a customer): a human personalises the reply');
  } else if (ai.confidence >= AUTO_SEND_MIN_CONFIDENCE && AUTO_SEND_CATEGORIES.includes(ai.category) && ticket.kb_matches > 0) {
    route = 'auto_reply';
    reasons.push(`Confident (${ai.confidence}) answer from knowledge base`);
  } else {
    route = 'draft';
    reasons.push(`Confidence ${ai.confidence} or category "${ai.category}" needs a human check`);
  }

  return {
    json: {
      ...ticket,
      ...ai,
      reply: String(ai.reply || '').replace(/\*\*(.+?)\*\*/g, '$1'), // plain-text email: strip markdown bold
      route,
      route_reason: reasons.join(', '),
    },
    pairedItem: { item: i },
  };
});

