// Daily KPI summary for the support manager
const today = $now.toISODate();
const tickets = $input.all().map(i => i.json).filter(t => (t.created_at || '').startsWith(today));

if (!tickets.length) {
  return [{ json: { text: `:bar_chart: *Support summary — ${today}*\nNo tickets today. :tada:` } }];
}

const LABELS = { auto_reply: 'Answered automatically', draft: 'Drafted for human review', escalate: 'Escalated', spam: 'Spam' };
const breakdown = key => Object.entries(
  tickets.reduce((acc, t) => ({ ...acc, [t[key]]: (acc[t[key]] || 0) + 1 }), {})
).sort((a, b) => b[1] - a[1]).map(([k, v]) => `• ${LABELS[k] || k}: ${v}`).join('\n');

const auto = tickets.filter(t => t.route === 'auto_reply').length;
const escalated = tickets.filter(t => t.route === 'escalate');
const avgConfidence = tickets.reduce((s, t) => s + (Number(t.confidence) || 0), 0) / tickets.length;

const text = [
  `:bar_chart: *Support summary — ${today}*`,
  `*${tickets.length}* tickets | *${Math.round(auto / tickets.length * 100)}%* answered automatically | avg AI confidence *${avgConfidence.toFixed(2)}*`,
  '',
  '*By category*', breakdown('category'),
  '',
  '*By outcome*', breakdown('route'),
  '',
  escalated.length ? `*Escalated (${escalated.length})*\n` + escalated.map(t => `• ${t.customer_name} — ${t.subject}`).join('\n') : '*No escalations* :white_check_mark:',
].join('\n');

return [{ json: { text, total: tickets.length, auto_resolved: auto, escalated: escalated.length } }];

// Combine each email with its CRM record and the knowledge-base articles the vector search found for it
const MIN_SCORE = 0.75; // similarity threshold (mistral-embed): below this an article is not considered relevant
const MAX_GAP = 0.03;   // also drop hits that score clearly lower than the best match for the same email
const TOP_K = 3;
const customers = $('Load customer DB').all().map(i => i.json);
const hits = $('Search knowledge base (RAG)').all();

return $('Normalize email').all().map((item, index) => {
  const email = item.json;
  const customer = customers.find(c => c.email === email.email);
  const articles = hits
    .filter((h, n) => {
      const p = Array.isArray(h.pairedItem) ? h.pairedItem[0] : h.pairedItem;
      return typeof p?.item === 'number' ? p.item === index : Math.floor(n / TOP_K) === index;
    })
    .filter(h => h.json.document && h.json.score >= MIN_SCORE)
    .filter((h, n, arr) => h.json.score >= Math.max(...arr.map(x => x.json.score)) - MAX_GAP)
    .map(h => ({
      topic: h.json.document.metadata?.topic || 'Article',
      text: h.json.document.pageContent,
      score: Math.round(h.json.score * 100) / 100,
    }));

  return {
    json: {
      ...email,
      is_customer: Boolean(customer),
      customer_name: customer?.name || email.name || 'Unknown',
      plan: customer?.plan || 'Not a customer',
      orders: customer?.orders || 0,
      lifetime_value: customer?.lifetime_value || 0,
      kb_matches: articles.length,
      kb_sources: articles.map(a => `${a.topic} (${a.score})`).join(', ') || 'none',
      kb_context: articles.length
        ? articles.map(a => a.text).join('\n\n')
        : 'No matching articles found.',
    },
    pairedItem: { item: index },
  };
});
